void compare(const Document& d,const std::vector<TileCanvasSurfaceOracle>& expected){
 for(int n=0;n<2;++n){const auto r=d.timeline().resolveSurface("c"+std::to_string(n));CHECK(r.surface&&r.source);const auto& s=*r.surface;const auto& e=expected[n];CHECK(s.width==e.width&&s.height==e.height&&s.offsetX==e.x&&s.offsetY==e.y&&hash(s)==e.hash);std::vector<int> payload;
  if(r.source->tilemap)for(const auto& cell:r.source->tilemap->cells)payload.push_back(cell?cell->rotation*4+(cell->flipHorizontal?1:0)+(cell->flipVertical?2:0):-1);
  if(r.source->freeTiles)for(const auto& i:r.source->freeTiles->instances){payload.push_back(std::stoi(i.id.substr(1)));payload.push_back(i.x);payload.push_back(i.y);const auto id=std::stoi(i.id.substr(1));CHECK(i.rotation==id%4&&i.flipHorizontal==(id%2==0)&&i.visible==(id!=2)&&i.locked==(id==4));}CHECK(payload==e.payload);
 }
}
void reopen(Document& d,const std::filesystem::path& p,const std::vector<TileCanvasSurfaceOracle>& expected){const auto before=d.timeline().state();project::saveDocumentAtomic(d,p);std::ifstream in(p,std::ios::binary);auto bytes=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto loaded=project::createEditableDocument(project::prepareEditableImport(project::readProjectManifest(bytes)));compare(loaded,expected);CHECK(loaded.width()==d.width()&&loaded.height()==d.height()&&loaded.timeline().state().tilesets[0].pixels==before.tilesets[0].pixels);CHECK(loaded.timeline().findCelById("c1")->linkedCelId==d.timeline().findCelById("c1")->linkedCelId&&loaded.timeline().state().frames[1].disabled);}
